package cli

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	posemodel "github.com/harne8/pose-mcp/internal/pose"
)

func TestZZReviewerRace(t *testing.T) {
	for _, mode := range []string{"resume-vs-handoff", "handoff-same-agent"} {
		root := handoffInstance(t)
		s := posemodel.Store{Root: root}
		runs, _ := s.ListReviewRuns("")
		prior := runs[0]
		before := map[string]bool{}
		walk := func(f func(string)) {
			filepath.Walk(filepath.Join(root, ".pose"), func(p string, i os.FileInfo, e error) error {
				if e == nil && !i.IsDir() {
					f(p)
				}
				return nil
			})
		}
		walk(func(p string) { before[p] = true })
		if code, out, errOut := runPoseSplit(t, root, "delegate", "handoff", prior.RunID, "--to", "continuer", "--json"); code != 0 {
			t.Fatal(code, out, errOut)
		}
		moved := map[string][]byte{}
		walk(func(p string) {
			if !before[p] {
				b, _ := os.ReadFile(p)
				moved[p] = b
				os.Remove(p)
			}
		})
		dir := filepath.Join(os.TempDir(), prior.Safety.RuntimeID)
		if err := os.Mkdir(dir, 0o700); err != nil {
			t.Fatal(err)
		}
		done := make(chan struct{})
		go func() {
			defer close(done)
			time.Sleep(900 * time.Millisecond)
			// receipt before claim, so the claim never shows without it
			for _, claimLast := range []bool{false, true} {
				for p, b := range moved {
					isClaim := filepath.Base(filepath.Dir(p)) == "review-continuations" && filepath.Base(p) == prior.RunID+".json"
					if isClaim == claimLast {
						os.WriteFile(p, b, 0o644)
					}
				}
			}
		}()
		var plan posemodel.DispatchPlan
		var err error
		if mode == "resume-vs-handoff" {
			plan, err = s.PlanReviewResume(prior.RunID)
		} else {
			plan, err = s.PlanReviewHandoff(prior.RunID, "continuer")
		}
		<-done
		os.Remove(dir)
		if plan.Existing != nil {
			t.Logf("%s: err=%v existing=%s adapter=%s handsOffFrom=%q", mode, err, plan.Existing.RunID, plan.Existing.Adapter, plan.Existing.HandsOffFrom)
			run, rerr := s.RunReviewDispatch(plan, time.Now)
			t.Logf("%s: dispatch run=%s err=%v", mode, run.RunID, rerr)
		} else {
			t.Logf("%s: err=%v pending=%v", mode, err, plan.PendingContinuation)
		}
		var again posemodel.DispatchPlan
		if mode == "resume-vs-handoff" {
			again, err = s.PlanReviewResume(prior.RunID)
		} else {
			again, err = s.PlanReviewHandoff(prior.RunID, "continuer")
		}
		t.Logf("%s: without the race: err=%v existing=%v", mode, err, again.Existing != nil)
	}
}
EOF
